  (select count(*) from public.sprin_kelompok sk join public.surat_perintah sp on sp.id=sk.surat_perintah_id where sp.nomor_lengkap in ('SPRIN/1819/VIII/PAM.1.3.2./2026','SPRIN/1827/VIII/PAM.1.3.2./2026','SPRIN/1836/VIII/PAM.1.3.2./2026','SPRIN/1835/VIII/PAM.1.3.2./2026','SPRIN/1833/VIII/PAM.3.3./2026','SPRIN/1844/VIII/PAM.1.3.2./2026','SPRIN/1850/VIII/PAM.1.3.2./2026','SPRIN/1845/VIII/PAM.3.3./2026','SPRIN/1854/VIII/PAM.1.3.2./2026','SPRIN/1848/VIII/PAM.3.3./2026','SPRIN/1867/VIII/PAM.1.3.2./2026','SPRIN/1883/VIII/PAM.1.3.2./2026')) as kelompok_masuk,
  (select count(*) from public.sprin_personel spr join public.sprin_kelompok sk on sk.id=spr.sprin_kelompok_id join public.surat_perintah sp on sp.id=sk.surat_perintah_id where sp.nomor_lengkap in ('SPRIN/1819/VIII/PAM.1.3.2./2026','SPRIN/1827/VIII/PAM.1.3.2./2026','SPRIN/1836/VIII/PAM.1.3.2./2026','SPRIN/1835/VIII/PAM.1.3.2./2026','SPRIN/1833/VIII/PAM.3.3./2026','SPRIN/1844/VIII/PAM.1.3.2./2026','SPRIN/1850/VIII/PAM.1.3.2./2026','SPRIN/1845/VIII/PAM.3.3./2026','SPRIN/1854/VIII/PAM.1.3.2./2026','SPRIN/1848/VIII/PAM.3.3./2026','SPRIN/1867/VIII/PAM.1.3.2./2026','SPRIN/1883/VIII/PAM.1.3.2./2026')) as personel_masuk;
